// @ts-check

import { RuntimeNameHandler } from '../../../utils/RuntimeNameHandler.js'
import { InMemoryConnectionData } from '../../../utils/connectionData/InMemoryConnectionData.js'
import { Http2ConnectionData } from '../../../utils/connectionData/Http2ConnectionData.js'
import { WsConnectionData } from '../../../utils/connectionData/WsConnectionData.js'
import { TcpConnectionData } from '../../../utils/nodejs/connectionData/TcpConnectionData.js'

/** @typedef {import('../../../utils/nodejs/connectionData/PluginConnectionData.js').PluginConnectionData} PluginConnectionData */

class ConfigResolver {
    /**
     * Parse a runtime string into the runtime enum/name using RuntimeNameHandler.
     * @param {string} runtime
     * @returns {*}
     */
    static tryParseRuntime(runtime) {
        return RuntimeNameHandler.getRuntime(String(runtime))
    }

    /**
     * Builds connection data from the host string from config (JSON, YAML, or connection string).
     * Recognized formats: "inmemory"/"in-memory", ws://..., wss://..., http(s)://...h2, tcp://host:port, host:port.
     * @param {string} hostValue
     * @returns {InMemoryConnectionData|WsConnectionData|Http2ConnectionData|TcpConnectionData|PluginConnectionData}
     */
    static buildConnectionData(hostValue) {
        if (!hostValue || String(hostValue).trim() === '') {
            throw new Error('Host value cannot be null or whitespace.')
        }

        const hv = String(hostValue).trim()
        const lower = hv.toLowerCase()

        // Explicit in-memory choice from config; no console message (intended by user).
        if (lower === 'inmemory' || lower === 'in-memory') {
            return new InMemoryConnectionData()
        }

        // WebSocket URL: use as-is for WsConnectionData.
        if (lower.startsWith('ws://') || lower.startsWith('wss://')) {
            return new WsConnectionData(hv)
        }

        // Http2 URL (http:// or https:// ends with h2)
        if (
            (lower.startsWith('http://') && lower.endsWith('h2')) ||
            (lower.startsWith('https://') && lower.endsWith('h2'))
        ) {
            return new Http2ConnectionData(hv)
        }

        if (lower.startsWith('tcp://') || hv.includes(':')) {
            return new TcpConnectionData(hv)
        }

        throw new Error(`Host value '${hv}' is not a recognized connection format.`)
    }

    /**
     * Look up a property on an object using a case-insensitive key match.
     * @param {Record<string, unknown>|null|undefined} obj
     * @param {string} property
     * @returns {unknown}
     */
    static getPropertyIgnoreCase(obj, property) {
        if (obj == null || typeof obj !== 'object') {
            return undefined
        }
        const target = String(property).toLowerCase()
        for (const key of Object.keys(obj)) {
            if (key.toLowerCase() === target) {
                return obj[key]
            }
        }
        return undefined
    }
}

export { ConfigResolver }
